/* Sotto guarded TX qualification stage.
 * A fixture of PUBLIC synthetic speech-codec frames generated by the
 * offline reference encoder, not live mic or private speech.
 * Default build cannot emit RF. Explicit armed bench build only; fixture
 * and watchdog confirmation are separate compile gates, no auto-install.
 * SPDX-License-Identifier: MIT */
#define K6_MODULE_LEVEL 5
#define K6_MODULE_OPT z
#define SOTTO_STAGE_MAX_FRAMES 26u
#include "../k6_mod.h"
#include "sotto_guard_tx.h"
K6_MODULE_NAME("SOTTO RFTEST");

#ifndef SOTTO_RF_BENCH
#define SOTTO_RF_BENCH 0
#endif
#if SOTTO_RF_BENCH
#if !SOTTO_RF_FIXTURE_ACK || !SOTTO_RF_WATCHDOG_ACK
#error "Explicit dummy-load and watchdog verification required"
#endif
#include "sotto_tx_fixture.inc"
static int cancel(const k6_api_t *a){
    return a->key_down() || (a->level>=25 && a->cancel_poll && a->cancel_poll()==1);
}
#endif

int k6_main(const k6_api_t *a){
    if(!a || a->abi!=1 || a->level<K6_MODULE_LEVEL)return -3;
#if !SOTTO_RF_BENCH
    a->say("SOTTO RFTEST inert");
    return -9;
#else
    uint32_t room=0;
    unsigned i;
    int rc;
    sotto_stage_t *s;
    if(a->rx_hz()!=433500000u || cancel(a) || km_power_switch_off())return -2;
    s=(sotto_stage_t*)a->scratch(&room);
    if(!s || ((uintptr_t)s&3u) || room<sizeof(*s))return -8;
    if(sotto_stage_begin(s,112,0x534f5454u,0x4f544553u))return -12;
    for(i=0;i<26u;i++)if(sotto_stage_record(s,fixture+6u*i))return -12;
    if(sotto_stage_seal(s,0,1))return -12;
    /* A separate, explicitly requested bench launch is the TX authorization.
       No activity happens on installation. Any local key aborts transmission. */
    rc=sotto_guard_tx(a,s,cancel);
    a->say(rc==6?"SOTTO RFTEST 6 sent":"SOTTO RFTEST stopped");
    return rc;
#endif
}
